private noncomputable def scaleVariables {σ : Type*} (c : ℝ)
    (P : MvPolynomial σ ℝ) : MvPolynomial σ ℝ :=
  ∑ d ∈ P.support, MvPolynomial.monomial d (c ^ d.degree * P.coeff d)

